package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

/** Native qualification and exact fresh locks. This fixture writes no permanent version decision or new generation. */
class CatalogVersionCommitPermitTest extends CatalogVersionQualificationTest {
    CatalogVersionCommitPermitService permits(){return new CatalogVersionCommitPermitService(f.source,f.tx,f.category);}
    CatalogVersionCommitPermitService.Captured capture(CatalogVersionCommitPermitService guard){return guard.capture("fictional-entity","fictional-analysis","fictional-current-item",f.clock.instant()).orElseThrow();}
    <T>T write(java.util.function.Supplier<T> work){return f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-version-fresh","fictional-root","c".repeat(64)),k->null,c->work.get());}
    @Test void FourCategoryFullProofRechecksBeforeTheOriginalWriterWithoutReparsingOldPayloads(){for(String category:List.of("agent","skill","workflow","model")){initialize(category,false);var guard=permits();var original=capture(guard);var p=write(()->guard.verify(original));assertSame(original.projection(),p);assertTrue(p.versionChanged());assertEquals(read().orElseThrow().currentProofHash(),p.resultConstraint().newProofHash());assertFalse(original.toString().contains("fictional"));assertEquals(1,f.sends);assertEquals(1,new JdbcJobRecords(f.source).byId(p.rootId()).callCount());}}
    @Test void ChangedNativeEntityContentInputClaimSendIntentBodyOrConfigRejectsAndTheCallerRollsBack(){for(String fault:List.of("entity","content","input","claim","send","intent","body","config")){initialize("agent",false);var guard=permits();var original=capture(guard);switch(fault){case "entity"->f.jdbc.update("UPDATE analyzed_entities SET revision=revision+1");case "content"->f.jdbc.update("UPDATE contents SET body_hash_v1=?",new byte[32]);case "input"->f.jdbc.update("UPDATE jobs SET payload_json=? WHERE owner_job_id=? AND purpose='input'","{\"fictional_changed\":true}",original.projection().rootId());case "claim"->f.jdbc.update("UPDATE jobs SET action_payload=? WHERE target_type='worker_claim'","{\"fictional_changed\":true}");case "send"->f.jdbc.update("UPDATE jobs SET send_authorized_at=NULL WHERE id=?",f.identity.attemptId());case "intent"->f.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE record_kind='generation_intent'");case "body"->f.jdbc.update("UPDATE source_run_items SET evidence_json=? WHERE id='fictional-current-item'","{\"fictional_changed\":true}");case "config"->f.jdbc.update("UPDATE source_runs SET config_snapshot_json=?","{\"parser_version\":\"fictional-parser-v1\",\"fictional_changed\":true}");}long before=f.jdbc.queryForObject("SELECT revision FROM analyzed_entities",Long.class);assertThrows(RuntimeException.class,()->write(()->{guard.verify(original);f.jdbc.update("UPDATE analyzed_entities SET revision=revision+1");return true;}));assertEquals(before,f.jdbc.queryForObject("SELECT revision FROM analyzed_entities",Long.class));}}
    @Test void UnknownIssuerWrongOuterOrWriterIsolationCannotTurnMissingProofIntoFalse(){var guard=permits();var original=capture(guard);assertThrows(RuntimeException.class,()->guard.verify(original));assertThrows(RuntimeException.class,()->write(()->permits().verify(original)));var tx=new TransactionTemplate(f.tx);tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(RuntimeException.class,()->tx.execute(s->guard.verify(original)));assertThrows(RuntimeException.class,()->tx.execute(s->capture(guard)));var wrong=new TransactionTemplate(f.tx);wrong.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(RuntimeException.class,()->wrong.execute(s->guard.verify(original)));f.jdbc.update("UPDATE analyzed_entities SET legacy_flag=1");assertTrue(guard.capture("fictional-entity","fictional-analysis","fictional-current-item",f.clock.instant()).isEmpty());assertEquals(1,f.sends);}
    @Test void CallerRollbackReleasesAllFreshLocksAndKeepsTheOriginalProofReusable(){var guard=permits();var original=capture(guard);long before=f.jdbc.queryForObject("SELECT revision FROM analyzed_entities",Long.class);assertThrows(RuntimeException.class,()->write(()->{guard.verify(original);f.jdbc.update("UPDATE analyzed_entities SET revision=revision+1");throw new IllegalStateException("fictional downstream failure");}));assertEquals(before,f.jdbc.queryForObject("SELECT revision FROM analyzed_entities",Long.class));assertSame(original.projection(),write(()->guard.verify(original)));assertEquals(1,f.sends);}
    void NativeLocksKeepAnIndependentSourceConfigWriterBlockedUntilTheOriginalCommit()throws Exception{var guard=permits();var original=capture(guard);var verified=new CountDownLatch(1);var release=new CountDownLatch(1);var started=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var first=pool.submit(()->write(()->{guard.verify(original);verified.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new IllegalStateException("fictional release timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return true;}));assertTrue(verified.await(10,TimeUnit.SECONDS));var second=pool.submit(()->{var independent=new TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(f.source));independent.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);return independent.execute(s->{started.countDown();f.jdbc.update("UPDATE source_runs SET config_snapshot_json=?","{\"parser_version\":\"fictional-parser-v1\",\"fictional_changed\":true}");return true;});});assertTrue(started.await(10,TimeUnit.SECONDS));assertThrows(TimeoutException.class,()->second.get(100,TimeUnit.MILLISECONDS));release.countDown();assertTrue(first.get(10,TimeUnit.SECONDS));assertTrue(second.get(10,TimeUnit.SECONDS));assertThrows(RuntimeException.class,()->write(()->guard.verify(original)));}finally{release.countDown();pool.shutdownNow();}}
}
